import json
from pathlib import Path
out=Path('docs/evidence');stage=Path('.tmp/ai15-timeout-deploy')
def read(path):return json.loads(Path(path).read_text(encoding='utf-8-sig'))
def save(name,value):
 target=out/('nodia-ai-ai15-timeout-'+name+'.json');target.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');return str(target)
infra=read('.tmp/ai15-timeout-infra-report.json');infra['snapshot_scope']='Before the combined diagnostic deployment; timestamps in each section identify the observed state.'
activation=read(stage/'activation-report.json');activation.update({'production_api_or_worker_restarted':False,'migrations_executed':False,'configured_database_modified':False,'production_profiles_mounted_in_unit_container':False,'unit_container_network':'none','unit_container_removed':True,'first_test_archive_packaging_error_corrected':'Synthetic catalog JSON fixture was absent from the first isolated unit-test archive; included before the final266/266 PASS. Image source did not change.'})
web_events=[json.loads(line) for line in (stage/'web-events.jsonl').read_text(encoding='utf-8-sig').splitlines() if line]
web_success=[event for event in web_events if event['event']=='web_success'];assert len(web_success)==1
web={'operation':'One user-authorized Web chat turn from the real UI','scope':'Conversation only, no MCP or delegation','bridge_image':activation['image'],'diagnostic':web_success[0]['web_generation'],'sql_observation':{'checked_at':'2026-10-16T20:38:31.606Z','new_run_state':'completed','completed_at':'2026-10-16T20:37:48.348Z','error_code':None,'provider_dispatches_used':1,'tool_calls_used':0,'mcp_rpc_messages_used':0,'delegations_used':0,'job_state':'done','open_attempts':0,'pending_jobs':0,'prompt_or_answer_read':False},'historical_run_preserved':'An earlier failed outcome_unknown run remains as history; the completed run is a new authorized turn, not a replay.','collector_scope':'Docker logs bounded by since/until and tail500, passed through the strict safe projection reader. An initial broad time window exceeded reader scan bounds; it was corrected without another generation.','safe_progress_events':web_events}
socket_events=[json.loads(line) for line in (stage/'socket-observer.jsonl').read_text(encoding='utf-8-sig').splitlines() if line];assert socket_events[-1]['event']=='terminal'
sockets={'scope':'Read-only bounded observation of the pinned CLI and its descendants during the single configured Agentic attestation','max_window_seconds':140,'hard_cap_seconds':150,'terminal':socket_events[-1],'event_count':len(socket_events),'max_established_per_process':max([p['tcp_states'].get('established',0) for event in socket_events for p in event.get('processes',[])],default=0),'additional_single_snapshot':{'cli_pid':250540,'established_non_loopback_https_connections':7,'peer_addresses_exported':False,'payloads_read':False},'limitations':['TCP established does not alone verify TLS, HTTP, authentication or model output.','Socket records omit all addresses, ports, arguments, environment and payloads.'],'events':socket_events}
paths=[save('infrastructure',infra),save('bridge-activation',activation),save('web-success',web),save('socket-observer',sockets),save('public-eligibility',read(stage/'public-eligibility.json'))]
for path in paths:read(path)
print(json.dumps({'evidence_files':paths,'json_valid':True,'new_generations':0}))
